create function private.deca_v1_expected_blueprints()
returns table(id uuid,blueprint_name text,category text,level text,version text,total_questions integer,distribution jsonb,source_topics jsonb)
language sql immutable set search_path=pg_catalog,pg_temp as $$
  select md5('liftoff:deca:prd-19.3-v1:'||(exam->>'key'))::uuid,exam->>'name',
    exam->>'category',exam->>'level','prd-19.3-v1',100,
    jsonb_build_object('schema_version',1,'strata',(
      select jsonb_agg(jsonb_build_object('id',t->>'id','priority',pos,'count',(t->>'count')::int,
        'tags',jsonb_build_array(t->>'tag')) order by pos)
      from jsonb_array_elements(exam->'topics') with ordinality a(t,pos)
      where (t->>'count')::int>0
    )),exam->'topics'
  from jsonb_array_elements(private.deca_v1_blueprint_manifest()) exam;
$$;

-- Reproducible bootstrap for new families only. Staff replacements are
-- published through the existing draft/activation workflow, not this seed.
create function private.provision_deca_v1_blueprints() returns integer
language plpgsql set search_path=pg_catalog,pg_temp as $$
declare b record; installed integer:=0; revision text:='V1 Founder Draft PRD section 19.3';
begin
  for b in select * from private.deca_v1_expected_blueprints() order by blueprint_name loop
    perform pg_advisory_xact_lock(hashtextextended('staff-blueprint:'||b.blueprint_name,0));
    if exists(select 1 from public.blueprint_versions v where v.id=b.id
      or (v.practice_parent_id is null and v.blueprint_name=b.blueprint_name)) then
      continue;
    end if;
    insert into public.blueprint_versions(id,blueprint_name,cluster,category,level,version,total_questions,distribution,status,change_reason)
      values(b.id,b.blueprint_name,b.category,b.category,b.level,b.version,b.total_questions,b.distribution,'Active',revision);
    -- Publish in the same transaction as validation and provenance. The
    -- approved manifest establishes these first-generation topic labels.
    perform private.validate_staff_blueprint_refs(private.canonicalize_staff_blueprint(b.id,b.version));
    insert into public.admin_audit_logs(action,resource_type,resource_id,reason,new_values)
      values('blueprint.activated','blueprint',b.id::text,revision,
        jsonb_build_object('status','Active','version',b.version,'source','PRD 19.3'));
    installed:=installed+1;
  end loop;
  return installed;
end;
$$;

revoke all on function private.deca_v1_blueprint_manifest(),private.deca_v1_expected_blueprints(),
  private.provision_deca_v1_blueprints() from public,anon,authenticated,service_role;
select private.provision_deca_v1_blueprints();
